// main.ts
import { NestFactory } from '@nestjs/core';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { AppModule } from './app.module';
import { setAppRef, setSwaggerConfig } from './spec.controller';

async function bootstrap(): Promise<void> {
  const app = await NestFactory.create(AppModule);

  const config = new DocumentBuilder()
    .setTitle('Academy API')
    .setVersion('1.0')
    .build();

  // NOTE: SwaggerModule.createDocument(app, config) is never called here —
  // no artifact gets built at bootstrap. The controller below builds its
  // own copy on demand instead.
  setAppRef(app);
  setSwaggerConfig(config);

  // The UI surface generates its own document independently of getSpec() —
  // a second generation path, not "one document, many surfaces".
  SwaggerModule.setup('docs', app, SwaggerModule.createDocument(app, config));

  await app.listen(3000);
}
bootstrap();

// spec.controller.ts
import { Controller, Get } from '@nestjs/common';
import type { INestApplication } from '@nestjs/common';
import { SwaggerModule } from '@nestjs/swagger';
import type { OpenAPIObject } from '@nestjs/swagger';

let appRef: INestApplication;
let swaggerConfig: Omit<OpenAPIObject, 'paths'>;

export function setAppRef(app: INestApplication): void {
  appRef = app;
}

export function setSwaggerConfig(config: Omit<OpenAPIObject, 'paths'>): void {
  swaggerConfig = config;
}

@Controller('api-json')
export class SpecController {
  @Get()
  getSpec(): OpenAPIObject {
    // BUG: rebuilds the entire OpenAPI document on every single request.
    // createDocument() re-walks every controller, route and DTO in the app
    // and reassembles an identical document each time it's invoked.
    const document = SwaggerModule.createDocument(appRef, swaggerConfig);
    return document;
  }
}
